    step_encode: "Koduję: {a}", step_bank: "Dodaję piosenki do banku muzyki: {a}", step_logic: "Zapisuję listę utworów…", step_cover: "Okładka: {a}", step_writeMod: "Zapisuję moda — to może potrwać minutę…",
    err_noGame: "Nie wskazano folderu gry.", err_noFmm: "Nie znaleziono Frosty Mod Manager.", err_noKey: "Frosty Mod Manager nie jest jeszcze ustawiony dla NFS Unbound: uruchom go raz i wybierz grę.",
    err_gameChanged: "Gra się zmieniła (aktualizacja?) — ta wersja narzędzia może do niej nie pasować. Poszukaj nowszego Unbound Soundtrack.",
    err_tooManySongs: "Za dużo włączonych piosenek: teraz zmieści się {a}. Wyłącz część piosenek — albo wyłącz więcej utworów gry: program może oddać część ich miejsc twoim piosenkom.", err_modLocked: "Nie mogę zapisać pliku moda — zamknij Frosty Mod Manager i spróbuj ponownie.",
    err_encodeFailed: "Koder nie poradził sobie z {a}.", err_encoderMissing: "Brak kodera — rozpakuj cały zip jeszcze raz.", err_songMissing: "Brak pliku piosenki — dodaj ją jeszcze raz.",
    err_busy: "Poczekaj — poprzednia praca jeszcze trwa.", err_tooLong: "Piosenka jest za długa (maks. 20 minut).", err_badImage: "Ten obrazek się nie nadaje.", err_ytLink: "To nie jest link YouTube / YT Music.", err_ytNoExe: "Nie znaleziono yt-dlp.exe — połóż go obok programu.", err_ytFail: "YouTube nie oddał piosenki: {a}", err_ytGone: "Film jest niedostępny na YouTube (zablokowany w Twoim kraju albo usunięty).", ytAlt: "Zastąpiono inną wersją z YT Music (ta sama piosenka, ta sama długość): {k}.", ytSize: "Pobiorę z internetu ≈ {dl}. Na dysku zajmie ≈ {disk} (piosenki w Music + dane programu), mod urośnie o ≈ {mod}. Wolne na dysku: {free}.", ytLag: "Podczas pobierania internet może zwolnić — filmy i gry online mogą lagować.", ytNoSpace: "Może zabraknąć miejsca!", ytAltLine: "zastąpiono wersją z YT Music", ytRetryLine: "YouTube odpowiedział 403, udało się za drugim razem", err_yt403: "YouTube chwilowo nie oddaje pliku (błąd 403). Spróbuj tę piosenkę później.", err_ytNet: "Brak internetu albo YouTube nie odpowiada.", uMB: "MB", uGB: "GB", cYt: "pobieranie piosenek z YouTube / YT Music (Unlicense), autorzy — zespół yt‑dlp",
