    save: "Salvar", del: "Excluir", decoding: "Lendo a música…", uploading: "Salvando a música…", badFile: "Não foi possível ler o arquivo",
    delT: "Excluir música?", delHtml: "<p>“{t}” sai da sua trilha. Seu arquivo de música continua onde está.</p><p>Gere o mod de novo para tirá-la do jogo.</p>", leaveT: "Sair sem salvar?", leaveHtml: "<p>As alterações nesta música serão perdidas.</p>", leaveNewHtml: "<p>A música ainda não foi salva — ela não será adicionada.</p>", leaveYes: "Sair", leaveNo: "Ficar", yes: "Sim", no: "Não",
