    changeHtml: "<p>Choisis quel dossier afficher à nouveau.</p>",
    changeGame: "Dossier du jeu",
    changeFmm: "Dossier de Mod Manager",
    docTitle: "Unbound Soundtrack",
    langT: "Langue",
    langPick: "Choisis ta langue",
